const [st, e] = os.stat('/')
console.log('os', e, (st.mode & os.S_IFMT).toString(8))
console.log('nlink', st.nlink)

const [before] = os.stat('/data/sub')
const f = std.open('/data/sub', 'r')
console.log(f === null ? 'refused' : 'opened')
const [after] = os.stat('/data/sub')
console.log('row survived', before.mode === after.mode && before.mtime === after.mtime, after.mode.toString(8))

os.mkdir('/data/newdir')
const f = std.open('/data/new.txt', 'w')
f.puts('x'.repeat(1000))
f.close()
const [a] = os.stat('/data/new.txt')
const [b] = os.stat('/data/seed.txt')
const [d] = os.stat('/data/newdir')
console.log(a.ino !== b.ino, a.ino === os.stat('/data/new.txt')[0].ino)
console.log(a.nlink, d.nlink, a.blocks)
console.log((a.mode & 0o777).toString(8), (d.mode & 0o777).toString(8))

program.node:
const fsp = require('node:fs').promises
await fsp.mkdir('/data/newdir')
await fsp.writeFile('/data/new.txt', 'x'.repeat(1000))
const a = await fsp.stat('/data/new.txt')
const b = await fsp.stat('/data/seed.txt')
const d = await fsp.stat('/data/newdir')
console.log(a.ino !== b.ino, a.ino === (await fsp.stat('/data/new.txt')).ino)
console.log(a.nlink, d.nlink, a.blocks, a.blksize)
console.log((a.mode & 0o777).toString(8), (d.mode & 0o777).toString(8))
